      },
      {
        "name": "No Deprecated Packages",
        "passed": true,
        "reason": "All dependencies (@azure/cosmos, typescript, @types/node, ts-node) are current packages. No deprecated azure-* or @azure/ms-rest-* packages."
      },
      {
        "name": "Logging via @azure/logger",
        "passed": false,
