        "passed": true,
        "reason": "Includes valid package.json with @azure/cosmos, tsconfig.json with appropriate settings, @types/node, and typescript devDependencies."
      },
      {
        "name": "@azure/cosmos npm package",
        "passed": true,
        "reason": "@azure/cosmos is listed as a dependency in package.json and imported in the code."
